#include "DmsLink.h"
#include <string.h>
namespace dms {uint16_t crc16Ccitt(const uint8_t*d,size_t n){uint16_t c=0xFFFF;while(n--){c^=uint16_t(*d++)<<8;for(int i=0;i<8;i++)c=c&0x8000?uint16_t(c<<1)^0x1021:uint16_t(c<<1);}return c;}size_t cobsEncode(const uint8_t*i,size_t n,uint8_t*o,size_t cap){if(!cap)return 0;size_t r=1,codeAt=0;uint8_t code=1;for(size_t k=0;k<n;k++){if(!i[k]){if(codeAt>=cap)return 0;o[codeAt]=code;codeAt=r++;code=1;}else{if(r>=cap)return 0;o[r++]=i[k];if(++code==0xFF){o[codeAt]=code;codeAt=r++;code=1;}}}if(codeAt>=cap)return 0;o[codeAt]=code;return r;}size_t cobsDecode(const uint8_t*i,size_t n,uint8_t*o,size_t cap){size_t r=0,k=0;while(k<n){uint8_t c=i[k++];if(!c||k+c-1>n)return 0;for(uint8_t j=1;j<c;j++){if(r>=cap)return 0;o[r++]=i[k++];}if(c<0xFF&&k<n){if(r>=cap)return 0;o[r++]=0;}}return r;}size_t encodeLink(const LinkFrame&f,uint8_t*out,size_t cap){if(f.length>DMSLINK_MAX_PAYLOAD)return 0;uint8_t raw[DMSLINK_MAX_RAW];size_t n=0;raw[n++]=0x44;raw[n++]=0x4D;raw[n++]=1;raw[n++]=f.type;raw[n++]=f.flags;raw[n++]=uint8_t(f.status);raw[n++]=f.transactionId;raw[n++]=f.transactionId>>8;raw[n++]=f.length;raw[n++]=f.length>>8;memcpy(raw+n,f.payload,f.length);n+=f.length;uint16_t c=crc16Ccitt(raw,n);raw[n++]=c;raw[n++]=c>>8;size_t w=cobsEncode(raw,n,out,cap?cap-1:0);if(!w||w>=cap)return 0;out[w++]=0;return w;}bool decodeLink(const uint8_t*w,size_t n,LinkFrame&f){if(n&&w[n-1]==0)n--;uint8_t r[DMSLINK_MAX_RAW];size_t z=cobsDecode(w,n,r,sizeof r);if(z<12||r[0]!=0x44||r[1]!=0x4D||r[2]!=1)return false;uint16_t len=r[8]|uint16_t(r[9])<<8;if(len>DMSLINK_MAX_PAYLOAD||z!=size_t(len)+12)return false;uint16_t got=r[z-2]|uint16_t(r[z-1])<<8;if(got!=crc16Ccitt(r,z-2))return false;f.type=r[3];f.flags=r[4];f.status=LinkStatus(r[5]);f.transactionId=r[6]|uint16_t(r[7])<<8;f.length=len;memcpy(f.payload,r+10,len);return true;}}
